//! The similarity terms of the partner market (genetics specification 4.2, 11.2): with the
//! traits of cognition and of the target height named in the data, the utility of a
//! candidate also falls with the squared differences of the two phenotypes at the round,
//! weighted by `w_K` and `w_H`. Without the traits (the base map) the terms drop out
//! (11.1).
//!
//! The expected bytes come from `tools/state_reference.py`, written from the design note of
//! the similarity and not from this code. Scenario "similar": seed 0xff, founder tag
//! `test:similar`, the test map `tests/golden/data_pairing` (40 own loci for each trait)
//! with the search height `c` = 1.0, six single women and six single men of 18 to 28 years
//! whose alleles at the 80 trait loci come from SplitMix64 started at 0 (every other locus
//! named at the reference allele, so that nobody draws at `Start`), ten rounds.

mod common;

use sim_core::data::Data;
use sim_core::data_id::DataId;
use sim_core::genome::{LocusAlleles, Sex};
use sim_core::input::{Founder, Input, Start};
use sim_core::log::{LogEntry, log_hash};
use sim_core::params::WorldParams;
use sim_core::time::SimTime;
use sim_core::world::{World, YearOut};

const Y: i64 = 31_449_600;
const MONTH: i64 = 2_419_200;

const PAIRING_DATA_HASH: u64 = 0x8bf3_743c_a83d_3062;
const SIMILAR_DATA_HASH: u64 = 0x94bc_1ee1_f9b7_ebc5;
const WITHOUT_TERMS_DATA_HASH: u64 = 0xe2e1_b389_759c_1614;
const SIMILAR_SAVE_BEFORE_PAIRING_ROUND: &str = "";
const SIMILAR_SAVE_AFTER_PAIRING_ROUND: &str = "";
const SIMILAR_SAVE_END_OF_ROUND_10: &str = "";
const SIMILAR_PARTNERED_ENTRIES: [&str; 6] = [
    "2680a8a702020004000c030101000313636f72653a706172746e65725f6d61726b65740415a6d2d9f0dfc5d1cf32018b9c93d398f3c6ca380501",
    "2a80a8a7020200030009030101000313636f72653a706172746e65725f6d61726b65740415e2cbefb8a5a3a6ae3f01a9dc9de8e886d990470502",
    "2e80d0ce04020005000b030101000313636f72653a706172746e65725f6d61726b65740415d194dfc9ffc0bcae7402a388cff5b4b48285af010503",
    "3280f8f5060200020008030101000313636f72653a706172746e65725f6d61726b65740415bf92f685ba8a83ebb101038cad85dac2c1c3f19f010504",
    "3680f8f506020006000a030101000313636f72653a706172746e65725f6d61726b65740415e1abe7d5cef4d3f339039fb9d9a9f1c0afeb2b0505",
    "3d80a09d090200010007030101000313636f72653a706172746e65725f6d61726b65740415e4e0e8defefdb9cab30104b2a1bca6d5d4e8ed1a0506",
];
const SIMILAR_FIRST_ENTRY_JSON: &str = r#"{"id":38,"t":2419200,"subjects":[{"sim":4},{"sim":12}],"causes":[{"plan":{"by":1,"planned_at":0}},{"rule":"core:partner_market"},{"random":{"tag":"0000000000000015","subject":"329f462dfe166926","occasion":"0000000000000001","detail":"38951b998a64ce0b"}}],"payload":{"core:partnered":{"partnership":1}}}"#;
const SIMILAR_LOG_HASH: u64 = 0x4e4e_95a5_c10b_1320;
const WITHOUT_TERMS_LOG_HASH: u64 = 0xd7d9_315f_3e58_904a;

fn hex(text: &str) -> Vec<u8> {
    (0..text.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&text[i..i + 2], 16).expect("hex digits"))
        .collect()
}

const CALIBRATION: &str =
    include_str!("../../../tests/golden/data_pairing/calibration/genetics.json");
const GENOME_MAP: &str =
    include_str!("../../../tests/golden/data_pairing/genetics/genome_map.json");

/// The test map with the traits named or not, and the search height `c`.
fn pairing_data(named: bool, height: Option<f64>) -> Data {
    let (mut calibration, genome_map) = common::files_from(CALIBRATION, GENOME_MAP);
    if !named {
        calibration["cognition_trait"] = serde_json::Value::Null;
        calibration["height_trait"] = serde_json::Value::Null;
    }
    let mut demography = common::demography();
    if let Some(c) = height {
        demography["values"]["core:market_search_height_female"]["value"] = serde_json::json!(c);
    }
    Data::new(common::definitions_with(demography, calibration, genome_map).expect("definitions"))
        .expect("checked")
}

/// The 80 trait loci of the test map in map order.
fn trait_loci() -> Vec<DataId> {
    let map: serde_json::Value = serde_json::from_str(GENOME_MAP).expect("json");
    map["loci"]
        .as_array()
        .expect("loci")
        .iter()
        .filter_map(|locus| locus["id"].as_str())
        .filter(|id| id.starts_with("test:cognition_") || id.starts_with("test:height_"))
        .map(|id| DataId::new(id).expect("id"))
        .collect()
}

/// SplitMix64 (Vigna), as `tools/state_reference.py` draws the alleles with it.
fn splitmix(state: &mut u64) -> u64 {
    *state = state.wrapping_add(0x9e37_79b9_7f4a_7c15);
    let mut z = *state;
    z = (z ^ (z >> 30)).wrapping_mul(0xbf58_476d_1ce4_e5b9);
    z = (z ^ (z >> 27)).wrapping_mul(0x94d0_49bb_1331_11eb);
    z ^ (z >> 31)
}

/// Founders of the given sexes and ages, each allele at the trait loci the top bit of the
/// next number of SplitMix64 from `state` (founder by founder, loci in map order, the
/// maternal copy first). Each founder names every locus of the map (the other loci at the
/// reference allele), so it draws nothing at `Start` (Grok F1).
fn founders(data: &Data, people: &[(Sex, i64)], state: &mut u64) -> Vec<Founder> {
    let loci = trait_loci();
    people
        .iter()
        .map(|&(sex, born)| {
            let named: Vec<LocusAlleles> = loci
                .iter()
                .map(|locus| {
                    let copies = [splitmix(state) >> 63, splitmix(state) >> 63]
                        .map(|bit| u8::try_from(bit).expect("a bit"));
                    LocusAlleles {
                        locus: locus.clone(),
                        copies: copies.to_vec(),
                    }
                })
                .collect();
            Founder {
                born: SimTime::from_secs(born),
                sex,
                alleles: common::fixed(data, sex, &named),
            }
        })
        .collect()
}

/// The `Start` of "similar" on `data`: six women, then six men, each of 18, 20, ..., 28
/// years.
fn similar_start(data: &Data) -> Input {
    let ages = [18, 20, 22, 24, 26, 28];
    let people: Vec<(Sex, i64)> = [Sex::Female, Sex::Male]
        .into_iter()
        .flat_map(|sex| ages.map(|age| (sex, -age * Y)))
        .collect();
    Input::Start(Start {
        world_seed: 0xff,
        founder_tag: DataId::new("test:similar").expect("valid"),
        world_params: WorldParams {
            hereditary_diseases: false,
            nutrition: Vec::new(),
        },
        founders: founders(data, &people, &mut 0),
        couples: Vec::new(),
        capacity: None,
        pool: None,
    })
}

struct Run {
    world: World,
    out: YearOut,
    log: Vec<LogEntry>,
}

impl Run {
    fn similar(named: bool) -> Run {
        let data = pairing_data(named, Some(1.0));
        let start = similar_start(&data);
        let mut world = World::new(data);
        world.submit(start).expect("accepted");
        let log = world.take_log();
        Run {
            world,
            out: YearOut::default(),
            log,
        }
    }

    fn advance(&mut self, until: i64) {
        self.world
            .advance_until(&mut self.out, SimTime::from_secs(until), &mut |_| false);
        self.log.extend(self.world.take_log());
    }

    fn save(&self) -> Vec<u8> {
        self.world.save(&self.out.year_hashes).expect("saves")
    }

    fn pairs(&self) -> Vec<(u64, u64, i64)> {
        self.world
            .pedigree()
            .partnerships
            .iter()
            .map(|p| (p.woman.get(), p.man.get(), p.formed.as_secs() / MONTH))
            .collect()
    }
}

#[test]
fn the_test_map_and_its_data() {
    assert_eq!(pairing_data(true, None).hash(), PAIRING_DATA_HASH);
    assert_eq!(pairing_data(true, Some(1.0)).hash(), SIMILAR_DATA_HASH);
    assert_eq!(
        pairing_data(false, Some(1.0)).hash(),
        WITHOUT_TERMS_DATA_HASH
    );
    assert_eq!(trait_loci().len(), 80);
    // The generator gives 941 alternative alleles of 1920 (`tools/state_reference.py`).
    let Input::Start(start) = similar_start(&pairing_data(true, Some(1.0))) else {
        unreachable!("a start")
    };
    let ones: usize = start
        .founders
        .iter()
        .flat_map(|f| &f.alleles)
        .map(|a| a.copies.iter().filter(|copy| **copy == 1).count())
        .sum();
    assert_eq!(ones, 941);
}

/// Ten rounds of "similar": in round 1 three women choose sim 12 and one sim 9; the first
/// gets sim 12, two get nobody. By round 4 all six are paired; every entry names the plan
/// of the round, the rule and the noise of the chosen man.
#[test]
fn similar_ones_pair() {
    let mut run = Run::similar(true);
    run.advance(MONTH - 1);
    assert_eq!(run.save(), hex(SIMILAR_SAVE_BEFORE_PAIRING_ROUND));
    run.advance(MONTH);
    assert_eq!(run.save(), hex(SIMILAR_SAVE_AFTER_PAIRING_ROUND));
    run.advance(10 * MONTH);
    assert_eq!(run.save(), hex(SIMILAR_SAVE_END_OF_ROUND_10));
    assert_eq!(
        run.pairs(),
        [
            (4, 12, 1),
            (3, 9, 1),
            (5, 11, 2),
            (2, 8, 3),
            (6, 10, 3),
            (1, 7, 4)
        ]
    );
    let partnered: Vec<&LogEntry> = run
        .log
        .iter()
        .filter(|entry| matches!(entry.payload, sim_core::log::LogPayload::Partnered { .. }))
        .collect();
    let bytes: Vec<Vec<u8>> = partnered
        .iter()
        .map(|entry| postcard::to_allocvec(entry).expect("encodes"))
        .collect();
    assert_eq!(bytes, SIMILAR_PARTNERED_ENTRIES.map(hex));
    assert_eq!(
        serde_json::to_string(partnered[0]).expect("json"),
        SIMILAR_FIRST_ENTRY_JSON
    );
    assert_eq!(log_hash(&run.log), SIMILAR_LOG_HASH);
}

/// Lever: the same world without the traits named chooses by age and noise alone, and
/// three of the six pairings differ (`tools/state_reference.py`).
#[test]
fn without_the_traits_the_choices_differ() {
    let mut run = Run::similar(false);
    run.advance(10 * MONTH);
    assert_eq!(
        run.pairs(),
        [
            (4, 12, 1),
            (5, 7, 1),
            (3, 9, 1),
            (6, 11, 2),
            (2, 8, 3),
            (1, 10, 4)
        ]
    );
    assert_eq!(log_hash(&run.log), WITHOUT_TERMS_LOG_HASH);
}
